practice.solution:
def convolve(x, h):
    if len(x) == 0 or len(h) == 0:
        return []
    y = []
    for i in range(len(x) + len(h) - 1):
        y.append(0)
    for i in range(len(x)):
        for j in range(len(h)):
            y[i + j] = y[i + j] + x[i] * h[j]
    return y

