practice.solution:
import math
def gain(b, w):
    re = 0.0
    im = 0.0
    for k in range(len(b)):
        re = re + b[k] * math.cos(w * k)
        im = im - b[k] * math.sin(w * k)
    return round(math.sqrt(re * re + im * im), 4)

