    pass

practice.solution:
import math
def lowpass_taps(cutoff, m):
    c = (m - 1) / 2.0
    h = []
    for k in range(m):
        u = 2 * cutoff * (k - c)
        if u == 0:
            s = 1.0
        else:
            s = math.sin(math.pi * u) / (math.pi * u)
        h.append(2 * cutoff * s)
    t = sum(h)
    out = []
    for v in h:
        out.append(round(v / t, 4))
    return out

