    # your code
    pass

practice.solution:
def pitch(x, fs, min_lag, max_lag):
    best = min_lag
    bv = None
    for lag in range(min_lag, max_lag + 1):
        s = 0.0
        for i in range(len(x) - lag):
            s = s + x[i] * x[i + lag]
        if bv is None or s > bv + 1e-9:
            bv = s
            best = lag
    return round(fs / float(best), 2)

