practice.solution:
def blur(img):
    h = len(img)
    w = len(img[0]) if h else 0
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            if r == 0 or c == 0 or r == h - 1 or c == w - 1:
                row.append(img[r][c])
            else:
                s = img[r][c] + img[r - 1][c] + img[r + 1][c] + img[r][c - 1] + img[r][c + 1]
                row.append(round(s / 5.0, 3))
        out.append(row)
    return out
